var NOTIFY_DEDUP_TTL = 500;
var NOTIFY_MAX_ENTRIES = 200;
function getLevel() {
  return Memory.logLevel || "info";
}
function shouldEmit(level) {
  if (level === "error" || level === "warn" || level === "info") {
    return true;
  }
  if (!Memory.debug) {
    return false;
  }
  return LEVELS[level] <= LEVELS[getLevel()];
}
function format(scope, level, msg, data) {
  const base = `[${Game.time}] [${level.toUpperCase()}] [${scope}] ${msg}`;
  if (data === undefined) {
    return base;
  }
  try {
    return `${base} ${JSON.stringify(data)}`;
  } catch {
    return `${base} [unserializable data]`;
  }
}
function notifyOnce(scope, level, msg) {
  if (typeof Game.notify !== "function") {
    return;
  }
