  const body = bodyFor(role, room.controller?.level ?? 1);
  if (!body) {
    return false;
  }
  const cost = bodyCost(body);
  if (spawn.store.energy < cost) {
    if (spawn.room.energyAvailable >= cost) {
      warn("spawn", `cannot spawn ${role} in ${room.name}: the spawn holds only ` + `${spawn.store.energy} of ${cost} energy — the rest sits in ` + "extensions, and spawnCreep only draws from the spawn itself");
