// src/roles/harvester.ts
function run(creep) {
  if (creep.store[RESOURCE_ENERGY] === 0 && runStepAside(creep)) {
    return;
  }
  const transferTarget = findEnergyTransferTarget(creep, [
    STRUCTURE_SPAWN,
    STRUCTURE_EXTENSION,
    STRUCTURE_TOWER,
    STRUCTURE_CONTAINER,
    STRUCTURE_STORAGE
