// src/expansion.ts
function run9() {
  const blacklist = Memory.expansionBlacklist || EXPANSION.blacklist || [];
  if (Memory.targetRoom && blacklist.indexOf(Memory.targetRoom) !== -1) {
    delete Memory.targetRoom;
  }
  if (!Memory._exitsCache) {
    Memory._exitsCache = {};
  }
  const home = findHomeRoom(Game.rooms);
  if (!home) {
    return;
  }
  if (!getExpansionGates(home, Game.gcl?.level)) {
    return;
  }
  if (!Memory.targetRoom) {
    const preferred = Memory.expansionPreferredTarget || EXPANSION.preferredTarget;
    const picked = pickExpansionTarget(home.name, Memory._exitsCache, blacklist, preferred, undefined);
    if (picked) {
      Memory.targetRoom = picked;
    }
    if (!Memory.targetRoom) {
      return;
    }
  }
  const targetRoomObject = Game.rooms[Memory.targetRoom];
  const counts = countExpansionCreeps(Memory.targetRoom);
  const decision = planExpansion(home, Memory.targetRoom, targetRoomObject, counts.rharvester, counts.reserver, counts.claimer);
  if (!decision.enabled || !decision.desiredRole) {
    return;
  }
  if (!canAffordBody(home, decision.desiredRole)) {
    return;
  }
  trySpawn(home, decision.desiredRole);
}

// src/utils/pixels.ts
function generatePixel() {
  if (Game.cpu && Game.cpu.bucket >= 1e4 && typeof Game.cpu.generatePixel === "function") {
    Game.cpu.generatePixel();
  }
}

// src/main.ts
console.log("Started script at", new Date().toISOString());
function loop() {
  tickStart();
  init();
  for (const name in Memory.creeps) {
    const mem = Memory.creeps[name];
    if (!Game.creeps[name] && mem) {
      const age = Game.time - (mem._birthTick || Game.time);
      recordCreepDeath(mem.role, age);
      delete Memory.creeps[name];
    }
  }
  for (const name in Game.creeps) {
    const creep = Game.creeps[name];
    if (!creep) {
      continue;
    }
    if (!creep.memory.homeRoom) {
      creep.memory.homeRoom = creep.room.name;
    }
    if (creep.memory._birthTick === undefined) {
      creep.memory._birthTick = Game.time;
    }
  }
  for (const roomName in Memory.rooms) {
    if (Game.rooms[roomName]) {
      continue;
    }
    const hasCreepWithHome = Object.values(Game.creeps).some((c) => c && c.memory && c.memory.homeRoom === roomName);
    if (!hasCreepWithHome) {
      delete Memory.rooms[roomName];
    }
  }
  if (Memory._exitsCache) {
    for (const roomName in Memory._exitsCache) {
      if (!Game.rooms[roomName]) {
        delete Memory._exitsCache[roomName];
      }
    }
  }
  if ("_tickStartCpu" in Memory) {
    delete Memory._tickStartCpu;
  }
  const ownedRoomNames = [];
  for (const roomName in Game.rooms) {
    const r = Game.rooms[roomName];
    if (!r) {
      continue;
    }
    if (r.controller && r.controller.my) {
      ownedRoomNames.push(roomName);
    }
  }
  if (ownedRoomNames.length === 0) {
    if (!Memory._knownSpawnIds) {
      Memory._knownSpawnIds = {};
    }
    let rescued = 0;
    for (const spawnId in Memory._knownSpawnIds) {
      const spawn = Game.getObjectById(spawnId);
      if (!spawn) {
        continue;
      }
      const roomName = spawn.room.name;
      ownedRoomNames.push(roomName);
      rescued++;
    }
    if (rescued === 0) {
      warn("main", "no owned rooms — bot is idle, respawn or claim a new room to recover");
      tickEnd();
      return;
    }
  }
  if (!Memory._knownSpawnIds) {
    Memory._knownSpawnIds = {};
  }
  for (const roomName of ownedRoomNames) {
    const r = Game.rooms[roomName];
    if (!r) {
      continue;
    }
    for (const spawn of r.find(FIND_MY_SPAWNS)) {
      Memory._knownSpawnIds[spawn.id] = true;
    }
  }
  for (const spawnId in Memory._knownSpawnIds) {
    const spawn = Game.getObjectById(spawnId);
    if (!spawn) {
      continue;
    }
    const room = spawn.room;
    if (room.controller && !room.controller.my) {
      delete Memory._knownSpawnIds[spawnId];
    }
  }
  for (const roomName of ownedRoomNames) {
    const r = Game.rooms[roomName];
    if (r) {
      run8(r);
    }
  }
  run9();
  generatePixel();
  tickEnd();
}
